FAR const char *vg_point_table_err_token(int ret)
{
  /* Stable tokens, not numbers: errno values differ across the board, the
   * host and the desktop tests.  Only [A-Za-z0-9_.-] may appear here.
   */

  switch (-ret)
    {
      case ENOENT:
        return "enoent";

      case EROFS:
        return "erofs";

      case ENOSPC:
        return "enospc";

      case ENOMEM:
        return "enomem";

      case EACCES:
        return "eacces";

      case EFBIG:
        return "efbig";

      case EINVAL:
        return "einval";

      default:
        return "eio";
    }
}

