# Reset, then poll a cheap storage probe on a fixed cadence and timestamp the
# answer.  Shows exactly when (and whether) the eMMC stops answering.
param(
  [string]$Port = "COM3",
  [int]$Baud = 115200,
  [int]$Rounds = 10,
  [int]$GapSec = 12,
  [string]$Probe = "vgcfg probe",
  [int]$BootSec = 20
)

$ErrorActionPreference = "Stop"

function Resolve-ExistingFile {
  param([string]$ExplicitValue, [string]$EnvironmentName, [string[]]$Candidates)
  $values = @($ExplicitValue, [Environment]::GetEnvironmentVariable($EnvironmentName)) + $Candidates
  foreach ($value in $values) {
    if (-not [string]::IsNullOrWhiteSpace($value) -and (Test-Path -LiteralPath $value -PathType Leaf)) {
      return (Resolve-Path -LiteralPath $value).Path
    }
  }
  throw "STM32CubeProgrammer CLI not found."
}

$candidates = @(
  "D:\Develop\STM32CubeCLT_1.21.0\STM32CubeProgrammer\bin\STM32_Programmer_CLI.exe",
  "D:\Develop\STM32CubeCLT\STM32CubeProgrammer\bin\STM32_Programmer_CLI.exe",
  (Join-Path $env:ProgramFiles "STMicroelectronics\STM32Cube\STM32CubeProgrammer\bin\STM32_Programmer_CLI.exe")
)
Get-ChildItem -Path "D:\Develop" -Filter "STM32CubeProgrammer" -Recurse -Directory -ErrorAction SilentlyContinue |
  ForEach-Object { $candidates = @((Join-Path $_.FullName "bin\STM32_Programmer_CLI.exe")) + $candidates }
$cli = Resolve-ExistingFile "" "STM32_PROGRAMMER_CLI" $candidates

$sp = New-Object System.IO.Ports.SerialPort
$sp.PortName = $Port
$sp.BaudRate = $Baud
$sp.ReadTimeout = 2000
$sp.DtrEnable = $false
$sp.RtsEnable = $false
$sp.Open()

& $cli -c port=SWD mode=UR -rst | Out-Null

$boot = ""
$deadline = (Get-Date).AddSeconds($BootSec)
while ((Get-Date) -lt $deadline) {
  if ($sp.BytesToRead -gt 0) { $boot += $sp.ReadExisting() }
  if ($boot -match "nsh>") { break }
  Start-Sleep -Milliseconds 150
}
$mount = if ($boot -match "eMMC mounted at /mnt/emmc") { "mounted" } else { "NOT-MOUNTED" }
Write-Host ("[{0:HH:mm:ss}] boot: eMMC {1}" -f (Get-Date), $mount)
if ($boot -match "(?m)^.*outside SRAM.*$") {
  Write-Host ("[{0:HH:mm:ss}] BOOT HAD A DROPPED TRANSFER" -f (Get-Date))
}

for ($i = 1; $i -le $Rounds; $i++) {
  Start-Sleep -Seconds $GapSec
  $sp.DiscardInBuffer()
  $sp.Write("$Probe`r")
  $buf = ""
  $deadline = (Get-Date).AddSeconds(10)
  while ((Get-Date) -lt $deadline) {
    if ($sp.BytesToRead -gt 0) { $buf += $sp.ReadExisting() }
    if ($buf -match "nsh>") { break }
    Start-Sleep -Milliseconds 120
  }
  $line = ($buf -split "`r?`n" | Where-Object { $_ -match "probe|ERR|outside SRAM|HARDFAULT" } | Select-Object -First 2) -join " | "
  if ($line -eq "") { $line = "<no answer>" }
  Write-Host ("[{0:HH:mm:ss}] round {1}: {2}" -f (Get-Date), $i, $line)
}

$sp.Close()
exit 0

# 常驻监控：定时探活，板子跑飞就自动复位救回来，并把崩溃现场留在日志里。
#
# 跑飞的两种形态都要能认：
#   1. 打印 HARDFAULT / Assertion / panic（会在日志里留下 dump）
#   2. 静默挂死：串口一个字节都不吐，连 CR 都不回 nsh>（没有任何提示，最阴的一种）
#
# 复位只能走 SWD。VCP 的 DTR 脉冲在这块板子上推不动目标，见
# .debug/nsh_reset_only.ps1 与 .debug/runaway-watch/NOTES.md。
#
# 用法（长跑，Ctrl-C 停）：
#   powershell.exe -ExecutionPolicy Bypass -File scripts/board_watch_recover.ps1
# 只观察不恢复（先看崩溃频率）：
#   ... -NoRecover

param(
  [string]$ComPort = "COM3",
  [int]$Baud = 115200,
  [int]$ProbeSec = 20,             # 探活间隔
  [int]$ProbeTimeoutSec = 8,       # 发 CR 后多久没等到 nsh> 算挂
  [int]$BootTimeoutSec = 60,       # 复位后等启动
  [int]$MaxRecoveries = 0,         # 0 = 不限次
  [switch]$NoRecover,              # 只记录，不自动复位
  [string]$LogPath = "",
  [string]$CubeCli = ""
)

$ErrorActionPreference = "Stop"

if ($LogPath -eq "") {
  $root = Split-Path -Parent $PSScriptRoot
  $LogPath = Join-Path $root ".debug\board_watch_recover.log"
}
New-Item -ItemType Directory -Force -Path (Split-Path $LogPath) | Out-Null

function Write-Log {
  param([string]$Text, [switch]$Raw)
  if ($Raw) {
    [System.IO.File]::AppendAllText($LogPath, $Text)
  } else {
    $line = "[watch] {0:yyyy-MM-ddTHH:mm:ss.fffzzz} $Text" -f (Get-Date)
    [System.IO.File]::AppendAllText($LogPath, $line + "`r`n")
    Write-Host $line
  }
}

function Resolve-CubeCli {
  param([string]$Explicit)
  $candidates = @(
    $Explicit,
    $env:STM32_PROGRAMMER_CLI,
    "D:\Develop\STM32CubeCLT_1.21.0\STM32CubeProgrammer\bin\STM32_Programmer_CLI.exe",
    "D:\Develop\STM32CubeCLT\STM32CubeProgrammer\bin\STM32_Programmer_CLI.exe",
    (Join-Path $env:ProgramFiles "STMicroelectronics\STM32Cube\STM32CubeProgrammer\bin\STM32_Programmer_CLI.exe")
  )
  Get-ChildItem -Path "D:\Develop" -Filter "STM32CubeProgrammer" -Recurse -Directory -ErrorAction SilentlyContinue |
    ForEach-Object { $candidates += (Join-Path $_.FullName "bin\STM32_Programmer_CLI.exe") }
  foreach ($c in $candidates) {
    if (-not [string]::IsNullOrWhiteSpace($c) -and (Test-Path -LiteralPath $c -PathType Leaf)) {
      return (Resolve-Path -LiteralPath $c).Path
    }
  }
  return $null
}

# 板端崩溃时会打的字。命中即认为跑飞，不等探活超时。
$panicPattern = "HARDFAULT|Assertion failed|panic:|stack_dump:|dump_tasks:"

$cli = $null
if (-not $NoRecover) {
  $cli = Resolve-CubeCli $CubeCli
  if ($null -eq $cli) {
    Write-Log "找不到 STM32CubeProgrammer CLI，无法自动复位。加 -NoRecover 可只观察。"
    exit 2
  }
}

$port = New-Object System.IO.Ports.SerialPort
$port.PortName = $ComPort
$port.BaudRate = $Baud
$port.ReadTimeout = 500
$port.DtrEnable = $false      # 不脉冲，避免连上就把板子复位
$port.RtsEnable = $false
try {
  $port.Open()
} catch {
  Write-Log "打不开 $ComPort ：$($_.Exception.Message)。先关掉其它串口监视器。"
  exit 2
}

Write-Log "start port=$ComPort probe=${ProbeSec}s noRecover=$NoRecover log=$LogPath"

$recoveries = 0
$panics = 0
$wedges = 0

function Read-Into {
  # 把串口现有字节吃干净，写进日志，返回本轮读到的文本
  $acc = ""
  while ($port.BytesToRead -gt 0) {
    $chunk = $port.ReadExisting()
    $acc += $chunk
    Write-Log $chunk -Raw
    if ($port.BytesToRead -eq 0) { Start-Sleep -Milliseconds 30 }
  }
  return $acc
}

function Wait-Prompt {
  param([int]$Seconds)
  $buf = ""
  $deadline = (Get-Date).AddSeconds($Seconds)
  while ((Get-Date) -lt $deadline) {
    $buf += Read-Into
    if ($buf -match "nsh>") { return @{ ok = $true; text = $buf } }
    Start-Sleep -Milliseconds 120
  }
  return @{ ok = $false; text = $buf }
}

function Recover {
  param([string]$Reason)

  $recoveries++
  Write-Log "RECOVER #$recoveries reason=$Reason"

  # 复位前把还能读到的现场留下（比如 panic 之后残留在缓冲里的字）
  [void](Read-Into)

  try {
    & $cli -c port=SWD mode=UR -rst | Out-Null
  } catch {
    Write-Log "SWD 复位失败：$($_.Exception.Message)"
    return
  }

  $boot = Wait-Prompt -Seconds $BootTimeoutSec
  Write-Log $boot.text -Raw

  if (-not $boot.ok) {
    Write-Log "RECOVER #$recoveries 复位后没等到 nsh>，板子可能没起来"
